code.java:
class Solution {
    public int minNumberOperations(int[] target){
        int answer=target[0];
        for(int i=1;i<target.length;i++)answer+=Math.max(0,target[i]-target[i-1]);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minNumberOperations(target:IntArray):Int{
        var answer=target[0];
        for(i in 1 until target.size)answer+=maxOf(0,target[i]-target[i-1]);
        return answer
    }
}

code.cpp:
class Solution {
    public: int minNumberOperations(vector<int>& target){
        int answer=target[0];
        for(int i=1;i<(int)target.size();++i)answer+=max(0,target[i]-target[i-1]);
        return answer;
    }
};
